#!/usr/bin/env python3
"""Assessment helper (22 Oct 2026): GA tagged to Inner Jakarta outlets but activated OUTSIDE Inner Jakarta (and with no activation site). Reads raw/GA*/Site_rguga_daily_outlet_202610.csv
(MSISDN never copied); writes aggregate CSVs to docs/assessments/ga_site_rguga/. Run from the project root: python3 scripts/assess_site_outflow.py"""
import os, csv, glob, json, subprocess, tempfile, collections as C
tmp = tempfile.mkdtemp()
subprocess.run(['node', '-e', """global.window=global;require('./website/data/ga_feed.js');const F=GA_FEED,fs=require('fs');
fs.writeFileSync(process.argv[1]+'/feed.json',JSON.stringify({loc_keys:F.metadata.loc_keys,outlets:F.outlets.map(r=>({i:r.i,b:r.b,mc:r.mc,br:r.br,dse:r.dse,t:r.t,sg:r.sg})),tkec:(F.metadata.target||{}).kec}))""", tmp], check=True)
F = json.load(open(tmp + '/feed.json'))
def nid(v):
    v = str(v or '').strip().upper()
    if v.endswith('.0'): v = v[:-2]
    return v.lstrip('0')
fo = {(r['b'], nid(r['i'])): r for r in F['outlets']}
mapping = {r['micro_cluster']: r for r in csv.DictReader(open('data/catalogues/gaplok_location_mapping.csv'))}
mc_area = {m: r['master_branch'] for m, r in mapping.items()}
U = set(F['loc_keys']); [U.add(t['kk']) for t in F['tkec'] or []]
f = glob.glob('raw/GA*/Site_rguga_daily_outlet_202610.csv')[0]
dest = C.defaultdict(C.Counter); by_area = C.defaultdict(C.Counter); by_mc = C.defaultdict(C.Counter); by_seg = C.defaultdict(C.Counter); site = C.defaultdict(C.Counter); sinfo = {}; dse = C.defaultdict(C.Counter)
tot = C.Counter(); dkab = C.defaultdict(C.Counter)
with open(f, newline='', encoding='utf-8') as fh:
    for row in csv.DictReader(fh):
        b = row['ga_brand']; oid = nid(row['outlet_id']); omc = row['outlet_micro_cluster']; fr = fo.get((b, oid))
        if fr is None and omc not in mapping: continue
        o_mc = omc if omc in mapping else fr['mc']; area = mc_area.get(o_mc, '(MC tidak dikenal)')
        ak = row['activation_kec_kabkot']; mb = row['datavol_mb']; g = mb != '' and float(mb) > 25
        seg = ('master ' + fr['sg']) if fr and fr['t'] == 'M' else ('non-master ' + (fr['sg'] or 'tanpa segmen') if fr else 'IJ')
        tot['tagged'] += 1; by_area[area]['tagged'] += 1; by_mc[o_mc]['tagged'] += 1; by_seg[seg]['tagged'] += 1; dse[fr['dse'] if fr else '(tanpa DSE)']['tagged'] += 1
        if not ak: cls = 'site_kosong'
        elif ak in U: cls = 'di_IJ'
        else: cls = 'luar_IJ'
        tot[cls] += 1; by_area[area][cls] += 1; by_mc[o_mc][cls] += 1; by_seg[seg][cls] += 1; dse[fr['dse'] if fr else '(tanpa DSE)'][cls] += 1
        if cls == 'luar_IJ':
            kab = row['activation_kabkot']; dest[kab]['all'] += 1; dest[kab]['gt25'] += g; dest[kab]['IM3'] += b == 'IM3'
            sid = row['activation_site_id']; site[sid]['all'] += 1; site[sid]['gt25'] += g; sinfo[sid] = (row['activation_site_name'], row['activation_kecamatan'], kab)
            dkab[kab][area] += 1; tot['luar_gt25'] += g
print(dict(tot))
for a, c in sorted(by_area.items(), key=lambda x: -x[1]['luar_IJ']): print(a, dict(c), round(c['luar_IJ'] / c['tagged'] * 100, 1))
for a, c in sorted(by_seg.items(), key=lambda x: -x[1]['luar_IJ']): print(a, dict(c), round(c['luar_IJ'] / c['tagged'] * 100, 1))
print('dest kab', [(k, v['all']) for k, v in sorted(dest.items(), key=lambda x: -x[1]['all'])[:60]]); print('n dest kab', len(dest), 'n sites', len(site))
PROV = {'BOGOR': 'JAWA BARAT', 'BANDUNG': 'JAWA BARAT', 'KOTA BOGOR': 'JAWA BARAT', 'KOTA BANDUNG': 'JAWA BARAT', 'CIANJUR': 'JAWA BARAT', 'CIREBON': 'JAWA BARAT', 'BANDUNG BARAT': 'JAWA BARAT', 'BANJAR': 'JAWA BARAT', 'GARUT': 'JAWA BARAT', 'SUKABUMI': 'JAWA BARAT', 'SUBANG': 'JAWA BARAT', 'KOTA CIREBON': 'JAWA BARAT', 'KOTA CIMAHI': 'JAWA BARAT', 'INDRAMAYU': 'JAWA BARAT', 'KOTA TASIKMALAYA': 'JAWA BARAT', 'KUNINGAN': 'JAWA BARAT', 'TASIKMALAYA': 'JAWA BARAT', 'SUMEDANG': 'JAWA BARAT', 'PURWAKARTA': 'JAWA BARAT', 'MAJALENGKA': 'JAWA BARAT', 'KOTA SUKABUMI': 'JAWA BARAT', 'KOTA BANJAR': 'JAWA BARAT', 'CIAMIS': 'JAWA BARAT', 'PANGANDARAN': 'JAWA BARAT', 'TANGERANG': 'BANTEN', 'KOTA TANGERANG': 'BANTEN', 'KOTA TANGERANG SELATAN': 'BANTEN', 'KOTA SERANG': 'BANTEN', 'KOTA CILEGON': 'BANTEN', 'SERANG': 'BANTEN', 'LEBAK': 'BANTEN', 'PANDEGLANG': 'BANTEN', 'JEPARA': 'JAWA TENGAH', 'MAGELANG': 'JAWA TENGAH', 'TEGAL': 'JAWA TENGAH', 'KUDUS': 'JAWA TENGAH', 'DEMAK': 'JAWA TENGAH', 'BANYUMAS': 'JAWA TENGAH', 'BREBES': 'JAWA TENGAH', 'KENDAL': 'JAWA TENGAH', 'KOTA SURAKARTA': 'JAWA TENGAH', 'KOTA SEMARANG': 'JAWA TENGAH', 'TEMANGGUNG': 'JAWA TENGAH', 'SUKOHARJO': 'JAWA TENGAH', 'BATANG': 'JAWA TENGAH', 'BANJARNEGARA': 'JAWA TENGAH', 'CILACAP': 'JAWA TENGAH', 'PEMALANG': 'JAWA TENGAH', 'PURBALINGGA': 'JAWA TENGAH', 'BOYOLALI': 'JAWA TENGAH', 'KLATEN': 'JAWA TENGAH', 'KEBUMEN': 'JAWA TENGAH', 'GROBOGAN': 'JAWA TENGAH', 'BLORA': 'JAWA TENGAH', 'KARANGANYAR': 'JAWA TENGAH', 'PURWOREJO': 'JAWA TENGAH', 'SRAGEN': 'JAWA TENGAH', 'KOTA SALATIGA': 'JAWA TENGAH', 'PEKALONGAN': 'JAWA TENGAH', 'SEMARANG': 'JAWA TENGAH', 'WONOGIRI': 'JAWA TENGAH', 'PATI': 'JAWA TENGAH', 'KOTA PEKALONGAN': 'JAWA TENGAH', 'KOTA TEGAL': 'JAWA TENGAH', 'WONOSOBO': 'JAWA TENGAH', 'REMBANG': 'JAWA TENGAH', 'KOTA MAGELANG': 'JAWA TENGAH', 'TUBAN': 'JAWA TIMUR', 'KOTA SURABAYA': 'JAWA TIMUR', 'GRESIK': 'JAWA TIMUR', 'MALANG': 'JAWA TIMUR', 'KEDIRI': 'JAWA TIMUR', 'KOTA KEDIRI': 'JAWA TIMUR', 'MAGETAN': 'JAWA TIMUR', 'BOJONEGORO': 'JAWA TIMUR', 'SIDOARJO': 'JAWA TIMUR', 'JOMBANG': 'JAWA TIMUR', 'TULUNGAGUNG': 'JAWA TIMUR', 'NGANJUK': 'JAWA TIMUR', 'JEMBER': 'JAWA TIMUR', 'NGAWI': 'JAWA TIMUR', 'MOJOKERTO': 'JAWA TIMUR', 'MADIUN': 'JAWA TIMUR', 'KOTA MALANG': 'JAWA TIMUR', 'PROBOLINGGO': 'JAWA TIMUR', 'KOTA MOJOKERTO': 'JAWA TIMUR', 'LAMONGAN': 'JAWA TIMUR', 'PASURUAN': 'JAWA TIMUR', 'BANYUWANGI': 'JAWA TIMUR', 'PONOROGO': 'JAWA TIMUR', 'SAMPANG': 'JAWA TIMUR', 'PAMEKASAN': 'JAWA TIMUR', 'LUMAJANG': 'JAWA TIMUR', 'KOTA BLITAR': 'JAWA TIMUR', 'BLITAR': 'JAWA TIMUR', 'KOTA PASURUAN': 'JAWA TIMUR', 'SUMENEP': 'JAWA TIMUR', 'SLEMAN': 'DI YOGYAKARTA', 'BANTUL': 'DI YOGYAKARTA', 'KOTA YOGYAKARTA': 'DI YOGYAKARTA', 'BULELENG': 'BALI', 'BADUNG': 'BALI', 'TABANAN': 'BALI', 'KOTA DENPASAR': 'BALI', 'KARANGASEM': 'BALI', 'BULUKUMBA': 'SULAWESI SELATAN', 'LUWU': 'SULAWESI SELATAN', 'KEPULAUAN SELAYAR': 'SULAWESI SELATAN', 'WAJO': 'SULAWESI SELATAN', 'KOTA MAKASSAR': 'SULAWESI SELATAN', 'SIDENRENG RAPPANG': 'SULAWESI SELATAN', 'PINRANG': 'SULAWESI SELATAN', 'KOTA PARE PARE': 'SULAWESI SELATAN', 'TAKALAR': 'SULAWESI SELATAN', 'KOTA PALOPO': 'SULAWESI SELATAN', 'SOPPENG': 'SULAWESI SELATAN', 'GOWA': 'SULAWESI SELATAN', 'POSO': 'SULAWESI TENGAH', 'KOTA PALU': 'SULAWESI TENGAH', 'DONGGALA': 'SULAWESI TENGAH', 'MOROWALI': 'SULAWESI TENGAH', 'TOLITOLI': 'SULAWESI TENGAH', 'TOJO UNA-UNA': 'SULAWESI TENGAH', 'MINAHASA SELATAN': 'SULAWESI UTARA', 'KOTA KOTAMOBAGU': 'SULAWESI UTARA', 'MINAHASA': 'SULAWESI UTARA', 'KOTA MANADO': 'SULAWESI UTARA', 'TANAH LAUT': 'KALIMANTAN SELATAN', 'HULU SUNGAI UTARA': 'KALIMANTAN SELATAN', 'KOTA BANJARMASIN': 'KALIMANTAN SELATAN', 'TANAH BUMBU': 'KALIMANTAN SELATAN', 'KOTA BANJARBARU': 'KALIMANTAN SELATAN', 'KOTABARU': 'KALIMANTAN SELATAN', 'BARITO KUALA': 'KALIMANTAN SELATAN', 'BENGKAYANG': 'KALIMANTAN BARAT', 'KETAPANG': 'KALIMANTAN BARAT', 'KOTA SINGKAWANG': 'KALIMANTAN BARAT', 'KOTA PONTIANAK': 'KALIMANTAN BARAT', 'LANDAK': 'KALIMANTAN BARAT', 'KUBU RAYA': 'KALIMANTAN BARAT', 'KOTAWARINGIN TIMUR': 'KALIMANTAN TENGAH', 'KOTA PALANGKARAYA': 'KALIMANTAN TENGAH', 'PASER': 'KALIMANTAN TIMUR', 'KUTAI BARAT': 'KALIMANTAN TIMUR', 'KUTAI TIMUR': 'KALIMANTAN TIMUR', 'KOTA BALIKPAPAN': 'KALIMANTAN TIMUR', 'KOTA PEKANBARU': 'RIAU', 'INDRAGIRI HULU': 'RIAU', 'KAMPAR': 'RIAU', 'INDRAGIRI HILIR': 'RIAU', 'BENGKALIS': 'RIAU', 'PELALAWAN': 'RIAU', 'KOTA BATAM': 'KEPULAUAN RIAU', 'BINTAN': 'KEPULAUAN RIAU', 'KOTA TANJUNGPINANG': 'KEPULAUAN RIAU', 'SIMALUNGUN': 'SUMATERA UTARA', 'DELI SERDANG': 'SUMATERA UTARA', 'KOTA MEDAN': 'SUMATERA UTARA', 'LABUHANBATU': 'SUMATERA UTARA', 'KOTA PADANG SIDIMPUAN': 'SUMATERA UTARA', 'KOTA PEMATANGSIANTAR': 'SUMATERA UTARA', 'TAPANULI SELATAN': 'SUMATERA UTARA', 'MANDAILING NATAL': 'SUMATERA UTARA', 'PADANG LAWAS': 'SUMATERA UTARA', 'TAPANULI UTARA': 'SUMATERA UTARA', 'TOBA SAMOSIR': 'SUMATERA UTARA', 'KOTA GUNUNGSITOLI': 'SUMATERA UTARA', 'NIAS': 'SUMATERA UTARA', 'NIAS UTARA': 'SUMATERA UTARA', 'SAMOSIR': 'SUMATERA UTARA', 'PADANG LAWAS UTARA': 'SUMATERA UTARA', 'OGAN KOMERING ULU SELATAN': 'SUMATERA SELATAN', 'PENUKAL ABAB LEMATANG ILIR': 'SUMATERA SELATAN', 'KOTA PALEMBANG': 'SUMATERA SELATAN', 'OGAN KOMERING ULU TIMUR': 'SUMATERA SELATAN', 'MUARA ENIM': 'SUMATERA SELATAN', 'OGAN KOMERING ILIR': 'SUMATERA SELATAN', 'BANYUASIN': 'SUMATERA SELATAN', 'LAMPUNG TIMUR': 'LAMPUNG', 'LAMPUNG SELATAN': 'LAMPUNG', 'KOTA BANDAR LAMPUNG': 'LAMPUNG', 'WAY KANAN': 'LAMPUNG', 'LAMPUNG TENGAH': 'LAMPUNG', 'PRINGSEWU': 'LAMPUNG', 'KAUR': 'BENGKULU', 'KOTA BENGKULU': 'BENGKULU', 'KOTA AMBON': 'MALUKU', 'MALUKU TENGAH': 'MALUKU', 'KOTA MATARAM': 'NTB', 'BANGKA': 'KEP. BANGKA BELITUNG', 'MIMIKA': 'PAPUA', 'SUMBA TIMUR': 'NTT', 'MANGGARAI': 'NTT', 'KOTA JAMBI': 'JAMBI', 'ACEH BESAR': 'ACEH', 'PIDIE': 'ACEH', 'ACEH TIMUR': 'ACEH'}
out = 'docs/assessments/ga_site_rguga'
def w(name, head, rows):
    with open(os.path.join(out, name), 'w', newline='') as fh: wr = csv.writer(fh); wr.writerow(head); wr.writerows(rows)
w('outflow_by_activation_kabupaten.csv', ['activation_kabupaten', 'ga_all', 'ga_usage_gt25', 'top_tagging_areas'], [(k, v['all'], v['gt25'], '; '.join('%s %d' % x for x in dkab[k].most_common(3))) for k, v in sorted(dest.items(), key=lambda x: -x[1]['all'])])
w('outflow_by_tagging_mc.csv', ['mc', 'area', 'ga_tagged', 'ga_activated_in_ij', 'ga_activated_outside_ij', 'ga_no_site', 'pct_outside_ij'], [(m, mc_area.get(m, ''), c['tagged'], c['di_IJ'], c['luar_IJ'], c['site_kosong'], round(c['luar_IJ'] / c['tagged'] * 100, 1)) for m, c in sorted(by_mc.items(), key=lambda x: -x[1]['luar_IJ'])])
w('outflow_by_activation_site.csv', ['site_id', 'site_name', 'kecamatan', 'kabupaten', 'ga_all', 'ga_usage_gt25'], [(s, *sinfo[s], v['all'], v['gt25']) for s, v in sorted(site.items(), key=lambda x: -x[1]['all'])])

pc = C.Counter(); pcg = C.Counter()
for k, v in dest.items(): p = PROV.get(k, '(kabupaten kecil < 10 GA, provinsi belum dipetakan)'); pc[p] += v['all']; pcg[p] += v['gt25']
print('PROVINSI', pc.most_common())
w('outflow_by_activation_province.csv', ['provinsi_aktivasi', 'ga_all', 'pct_of_outflow', 'ga_usage_gt25'], [(p, n, round(n / sum(pc.values()) * 100, 2), pcg[p]) for p, n in pc.most_common()])
